/// <summary>
/// PricingAttribute of table <c>SalesLine</c> field SalesDeliverNow.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesLine, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeSalesLineSalesDeliverNow extends UPSPricingAttributeSalesLine implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesLine, SalesDeliverNow);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Real);
    SalesLine   salesLine;

    while select salesLine
        group by SalesDeliverNow
    {
        if (! ret.in(salesLine.SalesDeliverNow))
        {
            ret.add(salesLine.SalesDeliverNow);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesLine, SalesDeliverNow));
    qbr.value(queryValue(_value));
}
